import React, { useState } from 'react';
import { ScrollText, AlertCircle, Info, AlertTriangle, X, Download } from 'lucide-react';
import { formatTimestamp } from '../utils/helpers';
import { ALERT_LEVELS, ALERT_COLORS } from '../utils/constants';

const SecurityLogs = ({ logs }) => {
  const [filter, setFilter] = useState('all');
  const [maxLogs, setMaxLogs] = useState(100);

  const getFilteredLogs = () => {
    let filtered = [...logs].reverse();

    if (filter !== 'all') {
      filtered = filtered.filter(log => log.level === filter);
    }

    return filtered.slice(0, maxLogs);
  };

  const getLevelIcon = (level) => {
    switch (level) {
      case ALERT_LEVELS.CRITICAL:
        return <AlertCircle size={16} />;
      case ALERT_LEVELS.WARNING:
        return <AlertTriangle size={16} />;
      case ALERT_LEVELS.INFO:
      default:
        return <Info size={16} />;
    }
  };

  const getLevelColor = (level) => {
    return ALERT_COLORS[level] || ALERT_COLORS.info;
  };

  const exportLogs = () => {
    const logText = logs.map(log => 
      `[${formatTimestamp(log.timestamp)}] [${log.level.toUpperCase()}] ${log.message}`
    ).join('\n');

    const blob = new Blob([logText], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `security-logs-${Date.now()}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const filteredLogs = getFilteredLogs();

  const criticalCount = logs.filter(l => l.level === ALERT_LEVELS.CRITICAL).length;
  const warningCount = logs.filter(l => l.level === ALERT_LEVELS.WARNING).length;
  const infoCount = logs.filter(l => l.level === ALERT_LEVELS.INFO).length;

  return (
    <div className="panel security-logs">
      <div className="panel-header">
        <h2>
          <ScrollText size={20} />
          Security Event Logs
        </h2>
        <button className="export-btn" onClick={exportLogs} title="Export logs">
          <Download size={16} />
        </button>
      </div>

      <div className="logs-summary">
        <div className="summary-item critical">
          <AlertCircle size={18} />
          <div>
            <span className="count">{criticalCount}</span>
            <span className="label">Critical</span>
          </div>
        </div>

        <div className="summary-item warning">
          <AlertTriangle size={18} />
          <div>
            <span className="count">{warningCount}</span>
            <span className="label">Warnings</span>
          </div>
        </div>

        <div className="summary-item info">
          <Info size={18} />
          <div>
            <span className="count">{infoCount}</span>
            <span className="label">Info</span>
          </div>
        </div>
      </div>

      <div className="logs-filters">
        <button 
          className={`filter-btn ${filter === 'all' ? 'active' : ''}`}
          onClick={() => setFilter('all')}
        >
          All Events
        </button>
        <button 
          className={`filter-btn ${filter === ALERT_LEVELS.CRITICAL ? 'active' : ''}`}
          onClick={() => setFilter(ALERT_LEVELS.CRITICAL)}
        >
          Critical
        </button>
        <button 
          className={`filter-btn ${filter === ALERT_LEVELS.WARNING ? 'active' : ''}`}
          onClick={() => setFilter(ALERT_LEVELS.WARNING)}
        >
          Warnings
        </button>
        <button 
          className={`filter-btn ${filter === ALERT_LEVELS.INFO ? 'active' : ''}`}
          onClick={() => setFilter(ALERT_LEVELS.INFO)}
        >
          Info
        </button>
      </div>

      <div className="logs-container">
        {logs.length === 0 && (
          <div className="empty-state">
            <ScrollText size={48} />
            <p>No security events logged</p>
            <span>Events will appear here as the system operates</span>
          </div>
        )}

        {filteredLogs.length === 0 && logs.length > 0 && (
          <div className="empty-state">
            <X size={48} />
            <p>No events match filter</p>
          </div>
        )}

        {filteredLogs.map(log => (
          <div 
            key={log.id} 
            className={`log-entry log-${log.level}`}
            style={{ borderLeftColor: getLevelColor(log.level) }}
          >
            <div className="log-icon" style={{ color: getLevelColor(log.level) }}>
              {getLevelIcon(log.level)}
            </div>
            <div className="log-content">
              <div className="log-header">
                <span className="log-time">{formatTimestamp(log.timestamp)}</span>
                <span 
                  className="log-level"
                  style={{ 
                    background: `${getLevelColor(log.level)}20`,
                    color: getLevelColor(log.level)
                  }}
                >
                  {log.level.toUpperCase()}
                </span>
              </div>
              <p className="log-message">{log.message}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="logs-footer">
        <span>Showing {filteredLogs.length} of {logs.length} events</span>
        {logs.length > 100 && (
          <button 
            className="load-more-btn"
            onClick={() => setMaxLogs(prev => prev + 100)}
          >
            Load More
          </button>
        )}
      </div>
    </div>
  );
};

export default SecurityLogs;
